package com.dy.artisan3d.ui.screen.main.article.detailimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.*import androidx.compose.foundation.rememberScrollStateimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.foundation.verticalScrollimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.ArrowBackimport androidx.compose.material.icons.filled.Personimport androidx.compose.material.icons.outlined.AccessTimeimport androidx.compose.material.icons.outlined.CalendarTodayimport androidx.compose.material3.*import androidx.compose.runtime.Composableimport androidx.compose.runtime.collectAsStateimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.articleimport artisan3d.composeapp.generated.resources.authorimport com.dy.artisan3d.ui.component.ArtisanHtmlTextimport com.dy.artisan3d.ui.component.Topbarimport org.jetbrains.compose.resources.stringResource@OptIn(ExperimentalMaterial3Api::class)@Composablefun ArtisanArticleDetailScreen(    viewModel: ArtisanArticleDetailViewModel,    onBack: () -> Unit) {    val scrollState = rememberScrollState()    val state = viewModel.uiState.collectAsState()    val article = state.value    Scaffold(        topBar = {            Topbar(                title = stringResource(Res.string.article),                onNavigationIcon = {                    IconButton(onClick = onBack) {                        Icon(                            imageVector = Icons.Default.ArrowBack,                            contentDescription = "Back"                        )                    }                }            )        }    ) { padding ->        Column(            modifier = Modifier                .fillMaxSize()                .verticalScroll(scrollState)        ) {            // Header Section with Gradient            Box(                modifier = Modifier                    .fillMaxWidth()                    .background(                        Brush.verticalGradient(                            colors = listOf(                                MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f),                                MaterialTheme.colorScheme.surface                            )                        )                    )                    .padding(top = padding.calculateTopPadding())                    .padding(horizontal = 20.dp)                    .padding(top = 24.dp, bottom = 32.dp)            ) {                Column {                    // Title                    Text(                        text = article.title,                        style = MaterialTheme.typography.headlineMedium,                        fontWeight = FontWeight.Bold,                        color = MaterialTheme.colorScheme.onSurface,                        lineHeight = 38.sp,                        letterSpacing = (-0.5).sp                    )                    Spacer(modifier = Modifier.height(20.dp))                    // Author Info Card                    ModernAuthorCard(author = article.author)                }            }            // Content Section            Column(                modifier = Modifier                    .fillMaxWidth()                    .padding(horizontal = 20.dp)                    .padding(top = 8.dp)            ) {                // Decorative Line                Box(                    modifier = Modifier                        .fillMaxWidth()                        .height(4.dp)                        .clip(MaterialTheme.shapes.small)                        .background(                            Brush.horizontalGradient(                                colors = listOf(                                    MaterialTheme.colorScheme.primary,                                    MaterialTheme.colorScheme.primary.copy(alpha = 0.3f)                                )                            )                        )                )                Spacer(modifier = Modifier.height(24.dp))                // HTML Content                ArtisanHtmlText(                    html = article.contentHtml,                    modifier = Modifier.fillMaxWidth()                )                Spacer(modifier = Modifier.height(12.dp))            }        }    }}@Composableprivate fun ModernAuthorCard(author: String) {    Surface(        modifier = Modifier.fillMaxWidth(),        shape = MaterialTheme.shapes.large,        color = MaterialTheme.colorScheme.surface,        tonalElevation = 2.dp,        shadowElevation = 4.dp    ) {        Row(            modifier = Modifier                .padding(16.dp),            verticalAlignment = Alignment.CenterVertically        ) {            // Author Avatar            Box(                modifier = Modifier                    .size(52.dp)                    .clip(CircleShape)                    .background(                        Brush.linearGradient(                            colors = listOf(                                MaterialTheme.colorScheme.primary,                                MaterialTheme.colorScheme.tertiary                            )                        )                    ),                contentAlignment = Alignment.Center            ) {                Icon(                    imageVector = Icons.Default.Person,                    contentDescription = null,                    modifier = Modifier.size(28.dp),                    tint = MaterialTheme.colorScheme.onPrimary                )            }            Spacer(modifier = Modifier.width(16.dp))            // Author Details            Column(                modifier = Modifier.weight(1f)            ) {                Text(                    text = stringResource(Res.string.author).uppercase(),                    style = MaterialTheme.typography.labelSmall,                    color = MaterialTheme.colorScheme.primary,                    fontWeight = FontWeight.SemiBold,                    letterSpacing = 1.2.sp,                )                Spacer(modifier = Modifier.height(4.dp))                Text(                    text = author,                    style = MaterialTheme.typography.titleMedium,                    fontWeight = FontWeight.Bold,                    color = MaterialTheme.colorScheme.onSurface                )            }        }    }}